function findAnchor(n: number, trust: number[][]): number {
  for (let c = 1; c <= n; c++) {
    let incoming = 0, outgoing = 0;
    for (const [a, b] of trust) {
      if (a === c) outgoing++;
      if (b === c) incoming++;
    }
    if (outgoing === 0 && incoming === n - 1) return c;
  }
  return -1;
}

