class Solution:
    def findAnchor(self, n: int, trust: List[List[int]]) -> int:
        for c in range(1, n + 1):
            out = sum(1 for a, _ in trust if a == c)
            inc = sum(1 for _, b in trust if b == c)
            if out == 0 and inc == n - 1:
                return c
        return -1

