function findAnchor(n: number, trust: number[][]): number {
  const score = new Array(n + 1).fill(0);
  for (const [a, b] of trust) {
    score[a]--;
    score[b]++;
  }
  for (let c = 1; c <= n; c++) if (score[c] === n - 1) return c;
  return -1;
}

